ی و آمار ۳","علوم و فنون ادبی ۳","عربی ۳ تخصصی","تاریخ ۳","جغرافیا ۳","جامعه‌شناسی ۳","فلسفه ۲","فارسی ۳","نگارش ۳","تعلیمات دینی ۳","زبان خارجی ۳","سلامت و بهداشت","مدیریت خانواده و سبک زندگی","تربیت بدنی ۳"]},"arts":{"9":["هوش و استعداد تحلیلی","ریاضی","علوم تجربی","فارسی","نگارش","مطالعات اجتماعی","عربی","زبان انگلیسی","کتاب کار زبان انگلیسی","آموزش قرآن","پیام‌های آسمان","کار و فناوری","فرهنگ و هنر","آمادگی دفاعی"],"10":["درک عمومی هنر","درک عمومی ریاضی و فیزیک","خلاقیت تصویری و تجسمی"],"11":["درک عمومی هنر","درک عمومی ریاضی و فیزیک","خلاقیت تصویری و تجسمی"],"12":["درک عمومی هنر","درک عمومی ریاضی و فیزیک","خلاقیت تصویری و تجسمی"],"null":["هوش و استعداد تحلیلی","ریاضی","علوم تجربی","فارسی","نگارش","مطالعات اجتماعی","عربی","زبان انگلیسی","کتاب کار زبان انگلیسی","آموزش قرآن","پیام‌های آسمان","کار و فناوری","فرهنگ و هنر","آمادگی دفاعی","درک عمومی هنر","درک عمومی ریاضی و فیزیک","خلاقیت تصویری و تجسمی"]},"foreign_languages":{"9":["هوش و استعداد تحلیلی","ریاضی","علوم تجربی","فارسی","نگارش","مطالعات اجتماعی","عربی","زبان انگلیسی","کتاب کار زبان انگلیسی","آموزش قرآن","پیام‌های آسمان","کار و فناوری","فرهنگ و هنر","آمادگی دفاعی"],"10":["زبان تخصصی"],"11":["زبان تخصصی"],"12":["زبان تخصصی"],"null":["هوش و استعداد تحلیلی","ریاضی","علوم تجربی","فارسی","نگارش","مطالعات اجتماعی","عربی","زبان انگلیسی","کتاب کار زبان انگلیسی","آموزش قرآن","پیام‌های آسمان","کار و فناوری","فرهنگ و هنر","آمادگی دفاعی","زبان تخصصی"]}}}$catalog$::jsonb;
 field text; grade integer; field_key text; grade_key text; previous_routines jsonb;
 entries jsonb; entry jsonb; routine jsonb; extra jsonb; topic jsonb; subject text; track text; activity text; publisher text;
 item_grade integer; i integer; seen integer[] := array[]::integer[]; allowed jsonb;
 today date := timezone('Asia/Tehran',now())::date;
begin
 if jsonb_typeof(snapshot) is distinct from 'object' or jsonb_typeof(snapshot->'title') is distinct from 'string'
  or jsonb_typeof(snapshot->'notes') is distinct from 'string'
  or length(snapshot->>'title')>120 or length(snapshot->>'notes')>2000
  or jsonb_typeof(snapshot->'items') is distinct from 'array' or jsonb_array_length(snapshot->'items')>100
  or jsonb_typeof(snapshot->'routines') is distinct from 'array' or jsonb_array_length(snapshot->'routines')<>7
  or target_week_start is null or target_week_start+6<today or (target_plan_id is null and target_week_start<today)
 then raise exception 'Invalid planner publication' using errcode='22023'; end if;
 if jsonb_array_length(snapshot->'items')=0 and not exists(select 1 from public.weekly_plans p where p.id=target_plan_id and p.status='published'::public.content_status) then
  raise exception 'Missing plan activities' using errcode='22023'; end if;
 select p.study_field::text,p.grade into field,grade from public.profiles p where p.id=target_student_id for share;
 if not found then raise exception 'Student not available' using errcode='42501'; end if;
 field_key:=case when catalog->'routines' ? coalesce(field,'null') then coalesce(field,'null') else 'null' end;
 grade_key:=case when grade in (9,10,11,12) then grade::text else 'null' end;
 allowed:=catalog->'routines'->field_key->grade_key;
 select p.routines into previous_routines from public.weekly_plans p where p.id=target_plan_id and p.counselor_id=(select auth.uid());
 for routine in select value from jsonb_array_elements(snapshot->'routines') loop
  if jsonb_typeof(routine) is distinct from 'object' or jsonb_typeof(routine->'dayOfWeek') is distinct from 'number'
   or (routine->>'dayOfWeek') !~ '^[0-6]$' then raise exception 'Invalid routine' using errcode='22023'; end if;
  i:=(routine->>'dayOfWeek')::integer;
  if i=any(seen) then raise exception 'Duplicate routine day' using errcode='22023'; end if;
  seen:=array_append(seen,i);
  foreach subject in array array[coalesce(routine->>'subject',''),coalesce(routine->>'secondSubject','')] loop
   subject:=btrim(subject);
   if length(subject)>100 or (subject<>'' and not (allowed ? subject) and not exists(
    select 1 from jsonb_array_elements(coalesce(previous_routines,'[]'::jsonb)) r
    where subject in (btrim(coalesce(r->>'subject','')),btrim(coalesce(r->>'secondSubject','')))
   )) then raise exception 'Invalid routine subject' using errcode='22023'; end if;
  end loop;
  if length(coalesce(routine->>'details',''))>500 or length(coalesce(routine->>'secondDetails',''))>500 then raise exception 'Invalid routine details' using errcode='22023'; end if;
 end loop;
 if jsonb_typeof(snapshot->'extras') is distinct from 'object'
  or jsonb_typeof(snapshot->'extras'->'week') is distinct from 'object'
  or jsonb_typeof(snapshot->'extras'->'items') is distinct from 'array'
  or jsonb_array_length(snapshot->'extras'->'items')<>jsonb_array_length(snapshot->'items') then
  raise exception 'Invalid plan metadata' using errcode='22023'; end if;
 foreach subject in array array['goal','wakeTime','sleepTime','mobileLimit'] loop
  if snapshot->'extras'->'week' ? subject and jsonb_typeof(snapshot->'extras'->'week'->subject) not in ('string','null') then raise exception 'Invalid week metadata' using errcode='22023'; end if;
 end loop;
 if length(coalesce(snapshot->'extras'->'week'->>'goal',''))>300 or length(coalesce(snapshot->'extras'->'week'->>'mobileLimit',''))>100
  or coalesce(snapshot->'extras'->'week'->>'wakeTime','') !~ '^([0-1][0-9]|2[0-3]):[0-5][0-9]$|^$'
  or coalesce(snapshot->'extras'->'week'->>'sleepTime','') !~ '^([0-1][0-9]|2[0-3]):[0-5][0-9]$|^$'
 then raise exception 'Invalid week metadata' using errcode='22023'; end if;
 for extra in select value from jsonb_array_elements(snapshot->'extras'->'items') loop
  if jsonb_typeof(extra) not in ('object','null') then raise exception 'Invalid item metadata' using errcode='22023'; end if;
  if jsonb_typeof(extra)='object' and extra ? 'topics' then
   if jsonb_typeof(extra->'topics') is distinct from 'array' or jsonb_array_length(extra->'topics')>50 then raise exception 'Invalid topics' using errcode='22023'; end if;
   for topic in select value from jsonb_array_elements(extra->'topics') loop
    if jsonb_typeof(topic) is distinct from 'object' or jsonb_typeof(topic->'title') is distinct from 'string' or btrim(topic->>'title')='' or length(topic->>'title')>160
     or (topic ? 'bankId' and jsonb_typeof(topic->'bankId') not in ('string','null')) or length(coalesce(topic->>'bankId',''))>200 then raise exception 'Invalid topic' using errcode='22023'; end if;
    if coalesce(topic->'pageStart','null'::jsonb)='null'::jsonb and coalesce(topic->'pageEnd','null'::jsonb)='null'::jsonb then continue; end if;
    if jsonb_typeof(topic->'pageStart') is distinct from 'number' or jsonb_typeof(topic->'pageEnd') is distinct from 'number'
      or topic->>'pageStart' !~ '^[0-9]{1,4}$' or topic->>'pageEnd' !~ '^[0-9]{1,4}$'
      or (topic->>'pageStart')::integer<1 or (topic->>'pageEnd')::integer<(topic->>'pageStart')::integer
    then raise exception 'Invalid topic pages' using errcode='22023'; end if;
   end loop;
  end if;
 end loop;
 entries:=snapshot->'items';
 for entry in select value from jsonb_array_elements(entries) loop
  if jsonb_typeof(entry) is distinct from 'object' or jsonb_typeof(entry->'dayOfWeek') is distinct from 'number'
   or (entry->>'dayOfWeek') !~ '^[0-6]$' or target_week_start+(entry->>'dayOfWeek')::integer<today
   or jsonb_typeof(entry->'durationMinutes') is distinct from 'number' or (entry->>'durationMinutes') !~ '^[0-9]{1,3}$'
   or (entry->>'durationMinutes')::integer not between 15 and 720
   or jsonb_typeof(entry->'subject') is distinct from 'string' or btrim(entry->>'subject')='' or length(entry->>'subject')>100
   or jsonb_typeof(entry->'chapter') is distinct from 'string' or length(entry->>'chapter')>160
   or jsonb_typeof(entry->'details') is distinct from 'string' or length(entry->>'details')>500
   or jsonb_typeof(entry->'activityType') is distinct from 'string'
  then raise exception 'Invalid planner activity' using errcode='22023'; end if;
  subject:=btrim(entry->>'subject');activity:=entry->>'activityType';track:=coalesce(entry->>'preparationTrack','konkur');publisher:=nullif(btrim(coalesce(entry->>'recommendedPublisher','')),'');
  if activity not in ('lesson','textbook_reading','notes','practice_tests','class','offline_class','exam','exam_analysis','exam_troubleshooting','simulation_exam','review','homework','summary','other','external_simulation_exam','makeup')
   or (entry ? 'preparationTrack' and jsonb_typeof(entry->'preparationTrack') not in ('string','null'))
   or (entry ? 'recommendedPublisher' and jsonb_typeof(entry->'recommendedPublisher') not in ('string','null'))
   or track not in ('konkur','final_exam') or (publisher is not null and (length(publisher)>80 or publisher ~ '[[:cntrl:]]' or track<>'konkur' or activity not in ('lesson','practice_tests','review','homework')))
   or (entry->'examYear' is not null and entry->'examYear'<>'null'::jsonb)
  then raise exception 'Invalid activity settings' using errcode='22023'; end if;
  if entry->'sourceGrade' is null or entry->'sourceGrade'='null'::jsonb then item_grade:=null;
  elsif jsonb_typeof(entry->'sourceGrade')='number' and entry->>'sourceGrade' in ('9','10','11','12') then item_grade:=(entry->>'sourceGrade')::integer;
  else raise exception 'Invalid activity grade' using errcode='22023'; end if;
  if activity='practice_tests' then
   if jsonb_typeof(entry->'targetTestCount') is distinct from 'number' or (entry->>'targetTestCount') !~ '^[0-9]{1,4}$' or (entry->>'targetTestCount')::integer not between 1 and 5000 then raise exception 'Invalid target test count' using errcode='22023'; end if;
  elsif entry->'targetTestCount' is distinct from 'null'::jsonb then raise exception 'Invalid target test count' using errcode='22023'; end if;
  if activity in ('makeup','external_simulation_exam') then
   if (activity='makeup' and subject<>'باکس جبرانی') or (activity='external_simulation_exam' and (subject not like 'آزمون شبیه‌ساز · %' or length(substr(subject,length('آزمون شبیه‌ساز · ')+1)) not between 2 and 60 or substr(subject,length('آزمون شبیه‌ساز · ')+1)<>btrim(substr(subject,length('آزمون شبیه‌ساز · ')+1)) or subject ~ '[[:cntrl:]]'))
    or coalesce(entry->>'chapter','')<>'' or item_grade is not null or track<>'konkur' or publisher is not null
   then raise exception 'Invalid special activity' using errcode='22023'; end if;
  elsif track='final_exam' then
   if item_grade is null or (not (coalesce(catalog->'finals'->field_key->item_grade::text,'[]'::jsonb) ? btrim(entry->>'subject'))
    and not (item_grade=9 and btrim(entry->>'subject')='تفکر و سبک زندگی' and exists (
     select 1 from public.weekly_plan_items old_item join public.weekly_plans old_plan on old_plan.id=old_item.plan_id
     where old_plan.id=target_plan_id and old_plan.student_id=target_student_id and old_plan.counselor_id=(select auth.uid())
      and old_item.subject=btrim(entry->>'subject') and old_item.id::text in (entry->>'id',entry->>'sourceItemId')
    ))) then raise exception 'Invalid school subject' using errcode='22023'; end if;
  elsif item_grade=9 and (subject<>'هوش و استعداد تحلیلی' or publisher is not null) then raise exception 'Invalid grade nine activity' using errcode='22023'; end if;
 end loop;
end; $$;
revoke all on function private.planner_validate_publication(uuid,uuid,date,jsonb) from public,anon,authenticated;
notify pgrst, 'reload schema';
